/* Orchestrator (simplified Node.js/TypeScript) */
interface Step { name: string; action: (o)=>Promise<void>; compensate: (o)=>Promise<void>; }

async function runSaga(order, steps: Step[]) {
  const done: Step[] = [];
  try {
    for (const s of steps) {
      await s.action(order);
      done.push(s);
      // persist progress: appendEvent({sagaId, step: s.name, status: 'done'})
    }
  } catch (err) {
    for (let i = done.length - 1; i >= 0; i--) {
      try { await done[i].compensate(order); }
      catch (e) { /* log, retry policies, escalate */ }
    }
    throw err;
  }
}

// Example step definitions must be idempotent and use idempotency keys where needed
const steps: Step[] = [
  { name: 'reserveInventory', action: reserveInventory, compensate: releaseInventory },
  { name: 'chargePayment', action: chargePayment,   compensate: refundPayment },
  { name: 'createShipment', action: createShipment,  compensate: cancelShipment }
];

// Usage
runSaga(order, steps).catch(e => console.error('Order failed', e));
